 8: export default function piWorktreeHud(pi: ExtensionAPI): void {
 9:   let runtime: SessionRuntime | undefined;
10:   let startupFailureNotified = false;
11: 
12:   const start = async (ctx: ExtensionContext) => {
13:     const started = await SessionRuntime.start(ctx, !startupFailureNotified);
14:     if (!started) startupFailureNotified = true;
15:     return started;
16:   };
17: 
18:   pi.on("session_start", async (_event, ctx) => {
19:     runtime?.dispose();
20:     startupFailureNotified = false;
21:     runtime = await start(ctx);
22:   });
23:   pi.on("session_shutdown", () => {
24:     runtime?.dispose();
25:     runtime = undefined;
26:   });
27:   pi.on("tool_execution_start", (event) =>
28:     runtime?.toolStart(event.toolCallId, event.toolName),
29:   );
30:   pi.on("tool_execution_end", (event) => runtime?.toolEnd(event.toolCallId));
31:   pi.on("agent_end", () => runtime?.agentEnd());
32:   pi.on("agent_settled", () => runtime?.clearAgentLocks());
33: 
34:   pi.on("message_end", () => runtime?.requestRefresh());
35:   pi.on("turn_end", () => runtime?.requestRefresh());
36: 
37:   const openShortcut = {
38:     description: "Open Worktree HUD",
39:     handler: (ctx: ExtensionContext) => {
40:       if (runtime) runtime.open();
41:       else
42:         void start(ctx).then((started) => {
43:           runtime = started;
44:           runtime?.open();
45:         });
46:     },
47:   };
48:   pi.registerShortcut(Key.ctrl("r"), openShortcut);
49:   pi.registerShortcut(Key.super("r"), openShortcut);
50: 
51:   pi.registerCommand("worktree-hud", {
52:     description:
53:       "Open, close, refresh, hide, show, or inspect the Worktree HUD",
54:     handler: async (args, ctx) => {
55:       const command = args.trim() || "open";
56:       if (!runtime && ["open", "show", "refresh"].includes(command))
57:         runtime = await start(ctx);
58:       if (command === "open") runtime?.open();
59:       else if (command === "close") runtime?.close();
60:       else if (command === "refresh") await runtime?.refresh();
61:       else if (command === "hide") runtime?.hide();
62:       else if (command === "show") runtime?.show();
63:       else if (command === "status")
64:         ctx.ui.notify(
65:           runtime?.status() ?? "Worktree HUD is not active",
66:           "info",
67:         );
68:       else
69:         ctx.ui.notify(
70:           "Usage: /worktree-hud [open|close|refresh|hide|show|status]",
71:           "warning",
72:         );
73:     },
74:   });
75: }

