  3: export interface ReconciledSnapshotStats {
  4:   snapshot: WorktreeSnapshot;
  5:   statusChanged: boolean;
  6:   requestStats: boolean;
  7: }
  8: 
  9: export function reconcileSnapshotStats(
 10:   previous: WorktreeSnapshot | undefined,
 11:   next: WorktreeSnapshot,
 12: ): ReconciledSnapshotStats {
 13:   const statusChanged = Boolean(
 14:     previous && snapshotStatusKey(previous) !== snapshotStatusKey(next),
 15:   );
 16:   const statsMissing = next.statsCapturedAt === undefined;
 17:   const trackedDirty = next.files.some((file) => file.recordType !== "?");
 18:   const snapshot =
 19:     statsMissing && previous
 20:       ? {
 21:           ...next,
 22:           additions: next.uniqueFileCount === 0 ? 0 : previous.additions,
 23:           deletions: next.uniqueFileCount === 0 ? 0 : previous.deletions,
 24:           binaryFileCount:
 25:             next.uniqueFileCount === 0 ? 0 : previous.binaryFileCount,
 26:           statsCapturedAt: previous.statsCapturedAt,
 27:         }
 28:       : next;
 29:   return {
 30:     snapshot,
 31:     statusChanged,
 32:     requestStats: statusChanged && statsMissing && trackedDirty,
 33:   };
 34: }
 35: 
 36: function snapshotStatusKey(snapshot: WorktreeSnapshot): string {
 37:   return `${snapshot.branch}\0${snapshot.completeness}\0${snapshot.files
 38:     .map(
 39:       (file) =>
 40:         `${file.recordType}\0${file.indexStatus}${file.worktreeStatus}\0${file.path}\0${file.originalPath ?? ""}`,
 41:     )
 42:     .join("\0")}`;
 43: }
