 51: type Reader = (
 52:   generation: number,
 53:   signal: AbortSignal,
 54: ) => Promise<WorktreeSnapshot>;
 55: 
 56: export class RefreshController {
 57:   readonly #reader: Reader;
 58:   readonly #commit: (snapshot: WorktreeSnapshot) => void;
 59:   readonly #fail: (error: string) => void;
 60:   #generation = 0;
 61:   #requestedGeneration = 0;
 62:   #running: Promise<void> | undefined;
 63:   #debounce: ReturnType<typeof setTimeout> | undefined;
 64:   #abort = new AbortController();
 65:   #disposed = false;
 66: 
 67:   constructor(
 68:     reader: Reader,
 69:     commit: (snapshot: WorktreeSnapshot) => void,
 70:     fail: (error: string) => void = () => undefined,
 71:   ) {
 72:     this.#reader = reader;
 73:     this.#commit = commit;
 74:     this.#fail = fail;
 75:   }
 76: 
 77:   get timerCount(): number {
 78:     return this.#debounce ? 1 : 0;
 79:   }
 80: 
 81:   get refreshing(): boolean {
 82:     return this.#running !== undefined;
 83:   }
 84: 
 85:   requestDebounced(): void {
 86:     if (this.#disposed) return;
 87:     this.#requestedGeneration += 1;
 88:     if (this.#debounce) return;
 89:     this.#debounce = setTimeout(() => {
 90:       this.#debounce = undefined;
 91:       void this.#ensureRunning();
 92:     }, 200);
 93:   }
 94: 
 95:   requestImmediate(): Promise<void> {
 96:     if (this.#disposed) return Promise.resolve();
 97:     if (this.#debounce) {
 98:       clearTimeout(this.#debounce);
 99:       this.#debounce = undefined;
100:     }
101:     this.#requestedGeneration += 1;
102:     return this.#ensureRunning();
103:   }
104: 
105:   dispose(): void {
106:     if (this.#disposed) return;
107:     this.#disposed = true;
108:     if (this.#debounce) clearTimeout(this.#debounce);
109:     this.#debounce = undefined;
110:     this.#abort.abort();
111:   }
112: 
113:   cancel(): void {
114:     if (this.#disposed) return;
115:     if (this.#debounce) clearTimeout(this.#debounce);
116:     this.#debounce = undefined;
117:     this.#abort.abort();
118:     this.#abort = new AbortController();
119:     if (!this.#running) this.#generation = this.#requestedGeneration;
120:   }
121: 
122:   #ensureRunning(): Promise<void> {
123:     if (!this.#running)
124:       this.#running = this.#run().finally(() => (this.#running = undefined));
125:     return this.#running;
126:   }
127: 
128:   async #run(): Promise<void> {
129:     while (!this.#disposed && this.#generation < this.#requestedGeneration) {
130:       const generation = this.#requestedGeneration;
131:       try {
132:         const snapshot = await this.#reader(generation, this.#abort.signal);
133:         this.#generation = generation;
134:         if (generation === this.#requestedGeneration && !this.#disposed)
135:           this.#commit(snapshot);
136:       } catch (error) {
137:         this.#generation = generation;
138:         if (!this.#disposed && generation === this.#requestedGeneration) {
139:           this.#fail(error instanceof Error ? error.message : String(error));
140:         }
141:       }
142:     }
143:   }
144: }
