146: export class PollController {
147:   readonly #tick: () => Promise<void> | void;
148:   readonly #now: () => number;
149:   #timer: ReturnType<typeof setTimeout> | undefined;
150:   #active = false;
151:   #lastActivity = 0;
152:   #interval = 0;
153: 
154:   constructor(tick: () => Promise<void> | void, now: () => number = Date.now) {
155:     this.#tick = tick;
156:     this.#now = now;
157:   }
158: 
159:   get interval(): number {
160:     return this.#interval;
161:   }
162: 
163:   get timerCount(): number {
164:     return this.#timer ? 1 : 0;
165:   }
166: 
167:   focus(): void {
168:     if (this.#active) return;
169:     this.#active = true;
170:     this.activity();
171:   }
172: 
173:   compact(): void {
174:     this.#active = false;
175:     if (this.#timer) clearTimeout(this.#timer);
176:     this.#timer = undefined;
177:     this.#interval = 0;
178:   }
179: 
180:   activity(): void {
181:     this.#lastActivity = this.#now();
182:     if (this.#active) this.#schedule();
183:   }
184: 
185:   #schedule(): void {
186:     if (this.#timer) clearTimeout(this.#timer);
187:     this.#interval = pollIntervalForQuietTime(this.#now() - this.#lastActivity);
188:     this.#timer = setTimeout(async () => {
189:       this.#timer = undefined;
190:       await this.#tick();
191:       if (this.#active) this.#schedule();
192:     }, this.#interval);
193:   }
194: }

