import type { MutationKind } from "../git/repository.js";
import type { WorktreeSnapshot } from "../state/model.js";

export interface FileSignature {
  exists: boolean;
  size?: number;
  mtimeMs?: number;
  mode?: number;
}

export interface MutationRequest {
  id: string;
  kind: MutationKind;
  generation: number;
  rowId?: string;
  path?: string;
  signature?: FileSignature;
  indexStatus?: string;
  indexOid?: string;
}

interface MutationQueueOptions {
  snapshot: () => WorktreeSnapshot | undefined;
  execute: (request: MutationRequest) => Promise<void>;
  refresh: () => Promise<boolean>;
  validate: (
    request: MutationRequest,
    snapshot: WorktreeSnapshot,
  ) => Promise<boolean>;
  onSkip?: (request: MutationRequest) => void;
  onError?: (error: string) => void;
}

export class MutationQueue {
  readonly #options: MutationQueueOptions;
  readonly #queue: MutationRequest[] = [];
  readonly #agentTools = new Set<string>();
  #running: Promise<void> | undefined;
  #unlock: Promise<void> | undefined;
  #agentRefreshPending = false;
  #disposed = false;
  #concurrent = 0;
  maxConcurrent = 0;

  constructor(options: MutationQueueOptions) {
    this.#options = options;
  }

  get queueLength(): number {
    return this.#queue.length;
  }

  get agentLockCount(): number {
    return this.#agentTools.size;
  }

  get agentRefreshPending(): boolean {
    return this.#agentRefreshPending;
  }

  enqueue(request: MutationRequest): boolean {
    if (
      this.#disposed ||
      this.#agentTools.size > 0 ||
      this.#agentRefreshPending
    )
      return false;
    this.#queue.push(request);
    void this.#pump();
    return true;
  }

  lockAgent(toolCallId: string): void {
    this.#agentTools.add(toolCallId);
  }

  unlockAgent(toolCallId: string, refreshNow = true): void {
    if (!this.#agentTools.delete(toolCallId) || this.#agentTools.size > 0)
      return;
    this.#refreshAfterAgent(refreshNow);
  }

  forgetAgent(toolCallId: string): void {
    this.#agentTools.delete(toolCallId);
  }

  clearAgentLocks(refreshNow = true): void {
    if (this.#agentTools.size === 0) return;
    this.#agentTools.clear();
    this.#refreshAfterAgent(refreshNow);
  }

  forgetAgentLocks(): void {
    this.#agentTools.clear();
  }

  refreshSucceeded(): void {
    if (!this.#agentRefreshPending) return;
    this.#agentRefreshPending = false;
    if (!this.#unlock) void this.#pump();
  }

  requestAgentRefresh(): void {
    this.#agentRefreshPending = true;
    const pending = this.#options
      .refresh()
      .then((success) => {
        if (success) this.refreshSucceeded();
      })
      .catch((error) => {
        this.#options.onError?.(
          error instanceof Error ? error.message : String(error),
        );
      });
    this.#unlock = pending.finally(() => {
      this.#unlock = undefined;
      if (!this.#agentRefreshPending) void this.#pump();
    });
  }

  async idle(): Promise<void> {
    while (this.#running || this.#unlock || this.#queue.length > 0) {
      await (this.#running ?? this.#unlock ?? Promise.resolve());
      await Promise.resolve();
    }
  }

  dispose(): void {
    this.#disposed = true;
    this.#queue.length = 0;
    this.#agentTools.clear();
  }

  #pump(): Promise<void> {
    if (
      this.#running ||
      this.#disposed ||
      this.#agentTools.size > 0 ||
      this.#agentRefreshPending ||
      this.#unlock
    ) {
      return this.#running ?? Promise.resolve();
    }
    this.#running = this.#drain().finally(() => {
      this.#running = undefined;
      if (
        this.#queue.length > 0 &&
        this.#agentTools.size === 0 &&
        !this.#unlock
      )
        void this.#pump();
    });
    return this.#running;
  }

  #refreshAfterAgent(refreshNow: boolean): void {
    this.#agentRefreshPending = true;
    if (!refreshNow) return;
